+/** Best supported language (`en` or `ko`) for an `Accept-Language` header, or `fallback`. */
+export function pickLanguage(header, fallback = process.env.LARDER_LANG === "ko" ? "ko" : "en") {
+  const def = LANGUAGES.includes(fallback) ? fallback : LANGUAGES[0];
+  let raw = header;
+  if (raw && typeof raw === "object") {
+    const entry = Object.entries(raw).find(([k]) => k.toLowerCase() === "accept-language");
+    raw = entry ? entry[1] : undefined;
+  }
+  if (Array.isArray(raw)) raw = raw.join(",");
+  if (typeof raw !== "string" || !raw.trim()) return def;
+
+  const choices = [];
+  for (const part of raw.split(",")) {
+    const trimmed = part.trim();
+    if (!trimmed) continue;
+    const [tagPart, ...params] = trimmed.split(";");
+    const tag = tagPart.trim();
+    if (!/^[a-zA-Z]{2,3}(-[a-zA-Z0-9]+)*$/.test(tag)) continue;
+    const lang = tag.split("-")[0].toLowerCase();
+    if (!LANGUAGES.includes(lang)) continue;
+
+    let q = 1;
+    let valid = true;
+    for (const p of params) {
+      const eq = p.indexOf("=");
+      if (eq === -1) {
+        valid = false;
+        break;
+      }
+      const k = p.slice(0, eq).trim().toLowerCase();
+      const v = p.slice(eq + 1).trim();
+      if (k === "q") {
+        const num = Number(v);
+        if (!v || Number.isNaN(num) || num < 0 || num > 1) {
+          valid = false;
+          break;
+        }
+        q = num;
+      }
+    }
+    if (valid && q > 0) choices.push({ lang, q });
+  }
+  if (!choices.length) return def;
+  choices.sort((a, b) => b.q - a.q);
+  return choices[0].lang;
+}
